/**
 * M9 / DEC-17: generate the Parkside block of src/styles/tokens.css
 * from design/parkside.tokens.json (light theme only).
 *
 * Hand-kept Barrio layout tokens stay below the generated block.
 * Do not edit the generated section by hand — run `npm run tokens`.
 */
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const source = JSON.parse(
  readFileSync(join(root, "design/parkside.tokens.json"), "utf8"),
);

function pxToRem(px) {
  const n = Number(String(px).replace(/px$/i, ""));
  if (Number.isNaN(n)) {
    throw new Error(`bad size: ${px}`);
  }
  return `${n / 16}rem`;
}

const colorLines = source.color.tokens.map((token) => {
  const light = token.value.light;
  return `  --color-${token.name}: ${light};`;
});

const typeFamilyLines = [
  `  --font-display: ${source.type.families.display};`,
  `  --font-sans: ${source.type.families.sans};`,
];

const typeSizeMap = {
  label: "text-label",
  "body-small": "text-body-small",
  body: "text-body",
  "heading-3": "text-heading-3",
  "heading-2": "text-heading-2",
  "heading-1": "text-heading-1",
  display: "text-display",
};

const typeSizeLines = [];
for (const group of source.type.groups) {
  for (const style of group.styles) {
    const cssName = typeSizeMap[style.name];
    if (!cssName) {
      continue;
    }
    typeSizeLines.push(`  --${cssName}: ${pxToRem(style.fontSize)};`);
  }
}

const spacingLines = source.spacing.tokens.map(
  (token) => `  --${token.name}: ${pxToRem(token.value)};`,
);

const radiusLines = source.radius.tokens.map((token) => {
  const value =
    token.name === "radius-pill" ? "9999px" : pxToRem(token.value);
  return `  --${token.name}: ${value};`;
});

const generated = `/**
 * GENERATED by scripts/build-tokens.mjs from design/parkside.tokens.json
 * Light theme only (DEC-23). Do not edit by hand — run: npm run tokens
 */
:root {
  /* Color (Parkside light) */
${colorLines.join("\n")}

  /* Type families */
${typeFamilyLines.join("\n")}

  /* Type sizes */
${typeSizeLines.join("\n")}

  /* Spacing (Parkside) */
${spacingLines.join("\n")}

  /* Radius */
${radiusLines.join("\n")}
}
`;

const handKept = `
/**
 * Barrio-only layout tokens (docs/SRD.md §11.3). Hand-kept — not in Parkside JSON.
 * Landing colors: mapped to Parkside where possible; see PR for no-match list.
 */
:root {
  --space-3: 0.75rem;
  --space-5: 1.25rem;
  --space-8: 2rem;
  --line-tight: 1.25;
  --line-normal: 1.5;
  --tap-min: 2.75rem; /* 44px */
  --shell-max: 26.875rem; /* 430px phone frame */
  --shell-sidebar: 14.5rem; /* desktop left nav (NAV-02) */
  --landing-max: 40rem;

  /* Aliases used by recover UI / landing (Parkside names preferred in new code) */
  --font-serif: var(--font-sans);
  --font-body-serif: var(--font-sans);
  --font-mono: var(--font-sans);
  --text-xs: var(--text-label);
  --text-sm: var(--text-body-small);
  --text-md: var(--text-body);
  --text-lg: var(--text-heading-3);
  --text-xl: var(--text-heading-3);
  --text-2xl: var(--text-heading-2);
  --text-3xl: var(--text-heading-1);
  --color-border: var(--color-line);
  --color-surface-elevated: var(--color-surface-raised);
  --color-brand: var(--color-primary);
  --color-brand-soft: var(--color-moss);
  --color-on-brand: var(--color-on-primary);
  --color-focus: var(--color-primary);
  --radius-full: var(--radius-pill);

  /* LAND-01 — closest Parkside mapping */
  --landing-paper: var(--color-surface);
  --landing-ink: var(--color-ink);
  --landing-muted: var(--color-ink-muted);
  --landing-accent: var(--color-primary);
  --landing-olive: var(--color-olive);
  /* No close Parkside match (kept for landing accents): */
  --landing-flush: #c45c48;
  --landing-sky: #6f6280;
}
`;

const LATIN =
  "U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD";
const LATIN_EXT =
  "U+0100-02BA, U+02BD-02C5, U+02C7-02CC, U+02CE-02D7, U+02DD-02FF, U+0304, U+0308, U+0329, U+1D00-1DBF, U+1E00-1E9F, U+1EF2-1EFF, U+2020, U+20A0-20AB, U+20AD-20C0, U+2113, U+2C60-2C7F, U+A720-A7FF";

function face(family, weight, fileBase) {
  return `@font-face {
  font-family: "${family}";
  font-style: normal;
  font-weight: ${weight};
  font-display: swap;
  src: url("/fonts/${fileBase}-latin-${weight}.woff2") format("woff2");
  unicode-range: ${LATIN};
}
@font-face {
  font-family: "${family}";
  font-style: normal;
  font-weight: ${weight};
  font-display: swap;
  src: url("/fonts/${fileBase}-latin-ext-${weight}.woff2") format("woff2");
  unicode-range: ${LATIN_EXT};
}`;
}

const fonts = `
/* Self-hosted Source Serif 4 (DEC-25). Latin + Latin Ext. Weights 400 & 600. */
${face("Source Serif 4", 400, "source-serif-4")}
${face("Source Serif 4", 600, "source-serif-4")}
`;

writeFileSync(
  join(root, "src/styles/tokens.css"),
  `${generated.trim()}\n${handKept.trim()}\n${fonts.trim()}\n`,
  "utf8",
);
console.log("Wrote src/styles/tokens.css");
